// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  GatewayRow.swift
//  Latchkey
//
//  F22: the app bar's row of gateways. One chip per remembered gateway, by
//  name, each with the dashboard's instance-bar light; one tap
//  on another switches to it directly. The dashboard's own instance bar
//  cannot do this from a phone: its remotes are plain-HTTP frames on the
//  gateway's loopback (F5 §5). These are gateways the app itself opens.
//
//  It lives in the bar, so it is there only when the bar is (F15): nothing
//  of it is on the page, and it adds no height.
//

import SwiftUI

struct GatewayRow: View {
    /// In order, by name (`GatewayChipState.order`); never empty.
    let origins: [String]
    let current: String
    /// The page in use: its load is the in-use chip's light.
    @ObservedObject var page: BrowserViewModel
    /// The node: whether it has a rule set yet, and which hosts it carries.
    @ObservedObject var tsnet: TSNetModel
    @ObservedObject var health: GatewayHealth
    let onSwitch: (String) -> Void

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 4) {
                ForEach(origins, id: \.self) { origin in
                    GatewayChip(origin: origin, inUse: origin == current, state: state(origin)) {
                        onSwitch(origin)
                    }
                }
            }
            .padding(.horizontal, 2)
        }
        .scrollBounceBehavior(.basedOnSize, axes: .horizontal)
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("gateway-row")
        // Probes only while the row is on screen, and again every
        // `freshFor` while it stays (F22 §4). Started again when the tailnet
        // becomes ready: the row is often up before the node is, and a
        // refresh then can probe nothing.
        .task(id: Probing(origins: others, ready: ready)) {
            while !Task.isCancelled {
                health.refresh(others)
                try? await Task.sleep(for: GatewayHealth.freshFor)
            }
        }
        .onDisappear { health.stop() }
    }

    private var others: [String] { origins.filter { $0 != current } }

    private var ready: Bool {
        tsnet.proxyConfiguration != nil && tsnet.proxyPolicy?.hasPeerData == true
    }

    private struct Probing: Equatable {
        let origins: [String]
        let ready: Bool
    }

    private func state(_ origin: String) -> GatewayChipState {
        if origin == current { return .current(Self.load(page.pageState)) }
        let host = URL(string: origin)?.host() ?? ""
        let policy = tsnet.proxyPolicy
        return .other(ready: policy?.hasPeerData == true,
                      carried: !host.isEmpty && policy?.matchingRule(for: host) != nil,
                      verdict: health.verdicts[origin])
    }

    static func load(_ state: PageState) -> GatewayChipState.Load {
        switch state {
        case .idle: return .idle
        case .holding, .connecting: return .connecting
        case .committed: return .committed
        case .failed: return .failed
        }
    }
}

/// One chip: the dashboard's `e8`, in SwiftUI. A bordered 26 pt capsule-ish
/// button, 12 pt text and a light; the one in use filled solid.
///
/// Its width is the name's and nothing else (issue #7): no state, load or
/// switch may resize a chip and shift the ones after it. So the state is a
/// symbol in a fixed slot, its shape as well as its colour, and the word is
/// the accessibility value; and the name reserves its bold width always.
private struct GatewayChip: View {
    let origin: String
    let inUse: Bool
    let state: GatewayChipState
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: 5) {
                Image(systemName: Self.symbol(state.light))
                    .font(.system(size: 10, weight: .bold))
                    .foregroundStyle(inUse ? Color.white : Self.color(state.light))
                    .frame(width: 12, height: 12)
                let name = GatewayChipState.shortName(origin)
                ZStack(alignment: .leading) {
                    Text(name).font(.system(size: 12, weight: .bold)).hidden()
                    Text(name).font(.system(size: 12, weight: inUse ? .bold : .regular))
                }
                .lineLimit(1)
                .truncationMode(.tail)
                .frame(maxWidth: 140, alignment: .leading)
                .fixedSize(horizontal: true, vertical: false)
            }
            .foregroundStyle(inUse ? Color.white : Color.primary)
            .padding(.horizontal, 8)
            .frame(height: 26)
            // Solid accent under white text: the one in use reads at a glance
            // over any page colour, light or dark. Every chip keeps an outline.
            .background {
                if inUse {
                    RoundedRectangle(cornerRadius: 6).fill(Color.accentColor)
                }
            }
            .overlay {
                RoundedRectangle(cornerRadius: 6)
                    .strokeBorder(inUse ? Color.accentColor : Color.secondary.opacity(0.35),
                                  lineWidth: inUse ? 1.5 : 1)
            }
            .background(.thinMaterial, in: RoundedRectangle(cornerRadius: 6))
            .frame(minHeight: 44)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        // The chip in use is not a switch, and a gateway off the tailnet may
        // not be chosen at all; the dimmed look is the not-enabled trait.
        .disabled(!state.tappable)
        .opacity(!state.tappable && !inUse ? 0.6 : 1)
        .accessibilityLabel(GatewayChipState.shown(origin) + (inUse ? ", in use" : ""))
        .accessibilityValue(state.word)
        .accessibilityIdentifier("gateway-chip-\(GatewayChipState.shown(origin))")
    }

    /// KiroCrew's `--ok`, `--warn`, `--danger` and `--muted`, as the system's
    /// own green, orange, red and grey, which adapt to light and dark.
    static func color(_ light: GatewayChipState.Light) -> Color {
        switch light {
        case .ok: return .green
        case .warn: return .orange
        case .danger: return .red
        case .muted: return .gray
        }
    }

    /// The light's shape, so colour is never the only signal (F22 §2).
    static func symbol(_ light: GatewayChipState.Light) -> String {
        switch light {
        case .ok: return "checkmark.circle.fill"
        case .warn: return "ellipsis.circle.fill"
        case .danger: return "exclamationmark.circle.fill"
        case .muted: return "minus.circle.fill"
        }
    }
}

// Copyright (c) 2026 Olof Johansson
// SPDX-License-Identifier: BSD-3-Clause

//
//  AppBar.swift
//  Latchkey
//
//  The one strip of the screen Latchkey owns while the dashboard is up (F15).
//
//  Latchkey may not assume it owns any part of the screen the page is using:
//  the dashboard draws its own controls in its corners, and the gear used to
//  sit on top of its notification bell. So the app's controls live in a bar
//  ABOVE the page, and the page starts where the bar ends. It is not an
//  overlay: an overlaying bar relies on the page insetting itself, and F9
//  measured this gateway ignoring the inset outside an installed web app.
//
//  The bar is absent in the steady state. A deliberate scroll up brings it
//  in and one down takes it away, Safari's model; a page that cannot scroll
//  always has it. `AppBarRetraction` is the policy and `AppBarController`
//  the reasons it must be on screen. Every change resizes the web view,
//  which is why the policy is strict and why Reduce Motion gets no
//  animation at all.
//

import SwiftUI

/// The bar above the page, then everything below it. The whole column's
/// layout animates together when the bar moves, so the page's top edge
/// follows the bar's bottom edge rather than jumping ahead of it.
struct AppBarColumn<Content: View>: View {
    @ObservedObject var model: BrowserViewModel
    @ObservedObject var controller: AppBarController
    let showsSignIn: Bool
    /// Keep the bar on screen for a reason other than sign-in: the gateway
    /// refusing this origin (F1 §4a) leaves the page inert, and the gear is
    /// then the owner's only way out.
    var pinnedForTrouble = false
    /// F22: the gateway row, for the bar's middle, or nil when there is no
    /// other gateway to show.
    var gatewayRow: AnyView? = nil
    let onSignIn: () -> Void
    let onSettings: () -> Void
    @ViewBuilder let content: Content

    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        VStack(spacing: 0) {
            AppBar(model: model, retracted: controller.retracted, showsSignIn: showsSignIn,
                   gatewayRow: gatewayRow, onSignIn: onSignIn, onSettings: onSettings)
            content
        }
        // The page's own canvas colour behind the bar and the status-bar strip
        // above it (F9 §0.1), so bar, strip and page read as one surface. A
        // view background does not reach into the safe area by itself.
        .background { PageTint(model: model).ignoresSafeArea() }
        // F21: what that colour was, report by report (test builds, on request).
        .pageBackgroundInstrument(model)
        .animation(AppBar.animation(reduceMotion: reduceMotion), value: controller.retracted)
        // The sign-in button must not be scrolled away: it is the only one.
        .onChange(of: showsSignIn || pinnedForTrouble, initial: true) { _, pinned in
            controller.setPinned(pinned)
        }
    }
}

struct AppBar: View {
    @ObservedObject var model: BrowserViewModel
    let retracted: Bool
    let showsSignIn: Bool
    var gatewayRow: AnyView? = nil
    let onSignIn: () -> Void
    let onSettings: () -> Void

    /// Reduce Motion: the bar and the page move in one step, not a slide.
    static func animation(reduceMotion: Bool) -> Animation? {
        reduceMotion ? nil : .easeOut(duration: 0.2)
    }

    var body: some View {
        // Retracted, the controls are REMOVED, not merely clipped away. A
        // zero-height clipped bar still lays its controls out, above itself,
        // under the status bar: invisible, and still hittable by accessibility
        // (L1 caught exactly that gear on the first run). An element that is
        // there and cannot be seen is the failure F15 §4b forbids. VoiceOver
        // and Switch Control never see this state at all (`AppBarController`).
        ZStack(alignment: .bottom) {
            if !retracted {
                HStack(spacing: 8) {
                    ReturnToDashboardAffordance(model: model)
                    if let gatewayRow {
                        // F22: the row starts where it always starts, and
                        // sign-in is a compact button AFTER it, beside the
                        // gear (issue #7): signing out must not push a chip
                        // sideways. Signed out is when a way to another
                        // gateway matters most, so neither hides the other.
                        gatewayRow
                            .frame(maxWidth: .infinity, alignment: .leading)
                        if showsSignIn {
                            compactSignIn
                                .layoutPriority(1)
                                .transition(.opacity)
                        }
                    } else {
                        Spacer(minLength: 0)
                        if showsSignIn { signIn }
                        Spacer(minLength: 0)
                    }
                    settings
                }
                .padding(.horizontal, 6)
                .frame(height: CGFloat(AppBarRetraction.barHeight))
            }
        }
        .frame(maxWidth: .infinity)
        // Zero height when retracted: the column closes over it and the web
        // view starts at the safe-area top.
        .frame(height: retracted ? 0 : CGFloat(AppBarRetraction.barHeight), alignment: .bottom)
        .clipped()
        .accessibilityElement(children: .contain)
        .accessibilityIdentifier("app-bar")
    }

    /// Settings, and through it the log viewer and the routing diagnostic:
    /// the reason the dashboard needs any chrome at all (PLAN §1.9).
    ///
    /// Full opacity. Over the page it used to be faded, and over a web view a
    /// button below full opacity gets no taps at all (M1–R29); in the bar it
    /// is not over anything. The material disc keeps it legible on whatever
    /// colour the page's canvas is.
    private var settings: some View {
        Button(action: onSettings) {
            Image(systemName: "gearshape.fill")
                .font(.system(size: 15, weight: .semibold))
                .foregroundStyle(.secondary)
                .padding(7)
                .background(.thinMaterial, in: Circle())
                .frame(width: 44, height: 44)
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityIdentifier("settings-button")
        .accessibilityLabel("Settings")
    }

    /// The way back to the sign-in sheet after closing it: the page's own
    /// banner is hidden (R22), so this is the only sign-in control.
    private var signIn: some View {
        Button(action: onSignIn) {
            Label("Signed out — Sign in", systemImage: "person.crop.circle.badge.exclamationmark")
                .font(.subheadline.weight(.semibold))
                .lineLimit(1)
                .minimumScaleFactor(0.8)
                .padding(.horizontal, 14)
                .padding(.vertical, 8)
                .background(.thinMaterial, in: Capsule())
        }
        .buttonStyle(.plain)
        .accessibilityIdentifier("session-signin-button")
    }

    /// The same way in, beside the row: text only, at the chips' fixed size,
    /// so it neither reads as a stray icon in the chip strip nor grows past
    /// the gear at the largest text.
    private var compactSignIn: some View {
        Button(action: onSignIn) {
            Text("Sign in")
                .font(.system(size: 12, weight: .semibold))
                .foregroundStyle(Color.primary)
                .lineLimit(1)
                .fixedSize()
                .padding(.horizontal, 10)
                .frame(height: 26)
                .overlay {
                    RoundedRectangle(cornerRadius: 6).strokeBorder(Color.orange, lineWidth: 1.5)
                }
                .background(.thinMaterial, in: RoundedRectangle(cornerRadius: 6))
                .frame(minHeight: 44)
                .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel("Signed out — Sign in")
        .accessibilityIdentifier("session-signin-button")
    }
}

/// The page's canvas colour, or the system background until it reports one
/// and on the app's own state pages (F9 §0.1).
private struct PageTint: View {
    @ObservedObject var model: BrowserViewModel

    var body: some View {
        guard model.pageState == .committed,
              let rgb = PageScriptSources.opaqueRGB(fromCSS: model.pageBackgroundCSS)
        else { return Color.platformSystemBackground }
        return Color(.sRGB, red: rgb.red, green: rgb.green, blue: rgb.blue)
    }
}

    /// including first launch, where `TabManager.init` seeds one.
    private func ensureFreshTab() {
        guard hasConnected, tabManager.tabCount == 0 else { return }
        tabManager.openChatTab()
    }
}

// MARK: - Dashboard (connected)

/// The app bar, the node's banners and one web view below them. Nothing of
/// the app's is drawn over the page (F15).
private struct DashboardContent: View {
    let workspace: Workspace
    @ObservedObject var homePage: HomePage
    @ObservedObject var model: TSNetModel
    @ObservedObject var tab: BrowserTab
    @ObservedObject var statusViewModel: StatusViewModel
    @ObservedObject var session: SessionManager
    let onSettings: () -> Void
    @State private var showingGatewayPicker = false
    /// A gateway chosen in the Find sheet, applied once the sheet is gone:
    /// the new gateway's page may ask for a token at once, and two sheets
    /// cannot overlap (M5 review; the same rule as Settings, M4).
    @State private var pendingGateway: String?
    /// How much of the bottom safe area the page takes (Olof, F13): 34pt on
    /// an iPhone 17 leaves 24, still clear of the home indicator.
    static let bottomReclaim: CGFloat = 10
    /// The bottom safe area without the keyboard's, measured by a reader that
    /// ignores the keyboard. Unmeasured, it is taken as "no keyboard".
    @State private var containerBottom = CGFloat.infinity

    var body: some View {
        Group {
            if homePage.hasGateway {
                NavigationStack {
                    // The stack hands its content the window's bottom safe area
                    // again, whatever is ignored outside it (F13): that is what
                    // ended the page 34pt above the screen edge. The page takes
                    // 10pt of it back and stays clear of the home indicator.
                    // With the keyboard up the inset is the keyboard's, which
                    // the stack already keeps the page above: padding by it
                    // again left the page no height at all, a black screen.
                    GeometryReader { geo in
                        let inset = geo.safeAreaInsets.bottom
                        let keyboardUp = inset > containerBottom + 0.5
                        gatewayContent
                            .padding(.bottom, keyboardUp ? 0 : max(0, inset - Self.bottomReclaim))
                            .ignoresSafeArea(.container, edges: .bottom)                    }
                    .background {
                        GeometryReader { geo in
                            Color.clear.onChange(of: geo.safeAreaInsets.bottom, initial: true) {
                                containerBottom = $1
                            }
                        }
                        .ignoresSafeArea(.keyboard)
                    }
#if canImport(UIKit)
                    .toolbar(.hidden, for: .navigationBar)
#endif
                }
            } else {
                // First run (M5): no gateway yet. Its own navigation stack,
                // not nested in the dashboard's toolbar-less one (M5 review).
                GatewayPickerView(discovery: workspace.discovery, model: model, saved: nil,
                                  autoSelectSingle: true,
                                  onSelect: { workspace.selectGateway($0) })
            }
        }
        // Lets the navigation stack reach the screen edge; the page's own
        // bottom edge is decided inside it, above.
        .ignoresSafeArea(.container, edges: .bottom)
        // No overlays (F15). Eight used to be painted over the page, at six
        // alignments, as though its corners were ours; the dashboard draws its
        // own controls there, and the gear landed on its notification bell.
        // The three controls went into the app bar (`AppBar`); the rest are
        // test instruments, below, in the status-bar corner. Do not add an
        // overlay back:
        // L1's testNothingOfOursSitsOnThePageAndSettingsIsReachable names any
        // hittable control of ours whose frame meets the web view's.
        // M5.5: re-probe when the chosen gateway is unreachable.
        .sheet(isPresented: $showingGatewayPicker, onDismiss: {
            if let origin = pendingGateway {
                pendingGateway = nil
                workspace.selectGateway(origin)
            }
        }) {
            GatewayPickerView(discovery: workspace.discovery, model: model,
                              saved: GatewayEndpoint(origin: homePage.url),
                              autoSelectSingle: false,
                              sweepOnAppear: true,
                              onSelect: { origin in
                                  pendingGateway = origin
                                  showingGatewayPicker = false
                              },
                              onCancel: { showingGatewayPicker = false })
        }
        // Test instruments, never controls, and never over the page: one point
        // of text each, in the top-leading corner of the status-bar strip.
        // Behind the web view was tried first and is not enough -- a view the
        // page covers still wins accessibility's hit test there, and L1's sweep
        // found all four "on the page". Testing builds only: "Connected
        // Browser" used to ship, as an invisible element VoiceOver read out
        // over the dashboard's bottom-right corner (F15 §9).
#if LATCHKEY_TEST_HOOKS
        .background(alignment: .topLeading) {
            ZStack(alignment: .topLeading) {
                // How many times the connecting block became visible for this
                // tab (F4 §4.7). A block that flashes up and away between two
                // looks is invisible to a poll but not to this number -- which
                // is the failure mode the 300 ms delay could introduce.
                Text("connecting-shown:\(tab.viewModel.connectingShownCount)")
                    .accessibilityIdentifier("page-connecting-shown-count")
                // How many times the page asked for a token, so a sheet that
                // flashes up and away between two looks is caught.
                Text("\(session.authRequiredEvents)")
                    .accessibilityIdentifier("session-auth-required-count")
                // A concrete element meaning "the dashboard is up". An
                // identifier applied to a container view is not reliably surfaced.
                Text("Connected Browser")
                    .accessibilityIdentifier("connected-browser")
                // F3: the inbox, the last share's outcome (counted, so one
                // that flashes by is not missed) and the content-process
                // deaths a 50 MB upload must not cause.
                ShareInstruments(delivery: ShareDelivery.shared, diagnostics: AppDiagnostics.shared)
                // F10 §4.5: the page's own report of its colliding items.
                if TestHooks.flag(PageSweep.flag) {
                    PageSweepInstrument(model: tab.viewModel)
                }
                if TSNetManager.tcpChaosTestRequested(),
                   let status = workspace.model.tcpChaosTestStatus {
                    Text(status)
                        .accessibilityIdentifier("tcp-chaos-test-status")
                }
#if canImport(UIKit)
                // F9 §0.2 / F15 §6: the window's safe-area top, for L1. It reads
                // the window, so where it sits does not matter.
                if TestHooks.flag("-UITestReportSafeArea") {
                    WindowSafeAreaProbe().frame(width: 1, height: 1)
                    WindowSafeAreaProbe(edge: .all).frame(width: 1, height: 1)
                }
#endif
            }
            .font(.system(size: 1))
            .lineLimit(1)
            .opacity(0.01)
            .allowsHitTesting(false)
            .ignoresSafeArea()
        }
#endif
        // With the toolbar gone, these are the hardware-keyboard paths to
        // Settings (which owns the log viewer) and to a reload. Defined here
        // so they stay available regardless of what has focus inside the web
        // content.
        .background {
#if !os(macOS)
            Group {
                Button("Settings") { onSettings() }
                    .keyboardShortcut(",", modifiers: .command)
                Button("Reload") { tab.viewModel.reload() }
                    .keyboardShortcut("r", modifiers: .command)
            }
            .hidden()
#endif
        }
    }

    /// The sign-in button in the app bar. Keyed on the sheet being ON SCREEN,
    /// not requested: a deferred request must not hide the only way in (M4
    /// review). Not while the node itself is down: its banner comes first, and
    /// no dashboard sign-in can work until it is back (R31 review).
    private var showsSignIn: Bool {
        session.state == .needsToken && !session.isTokenSheetOnScreen
            && !statusViewModel.needsAuth && !statusViewModel.needsMachineAuth
    }

    /// F22: the remembered gateways, in the app bar, when there is another
    /// one to switch to. A tap is the picker's own apply path; the rule is
    /// checked again first, as the chip's state may be a moment old.
    private var gatewayRow: AnyView? {
        let origins = GatewayChipState.order(current: homePage.url,
                                             known: workspace.definition.knownGatewayOrigins)
        guard !origins.isEmpty else { return nil }
        return AnyView(GatewayRow(origins: origins, current: homePage.url, page: tab.viewModel,
                                  tsnet: model, health: workspace.gatewayHealth) { origin in
            guard origin != homePage.url, let host = URL(string: origin)?.host(),
                  model.proxyPolicy?.matchingRule(for: host) != nil else { return }
            workspace.selectGateway(origin)
        })
    }

    private var gatewayContent: some View {
        // The app bar, then the page (F15). The banners are between them: in
        // the layout like the page, never over it, and they stay when the bar
        // retracts (F15 §9 argues their place).
        AppBarColumn(model: tab.viewModel, controller: tab.viewModel.appBar,
                     showsSignIn: showsSignIn,
                     pinnedForTrouble: session.originCheck == .refused,
                     gatewayRow: gatewayRow,
                     onSignIn: { session.isTokenSheetPresented = true },
                     onSettings: onSettings) {
            // The node's own trouble first, in the layout rather than over it
            // (R31 review): an overlay covered the gateway banner's buttons and
            // was itself covered by the sign-in capsule.
            if statusViewModel.needsAuth {
                // Mid-session NeedsLogin -- the node key expired, or was
                // expired by an admin (R31): Login re-authenticates in place.
                LoginBanner(
                    authSessionEndedGeneration: statusViewModel.authSessionEndedGeneration,
                    onLogin: { statusViewModel.showAuth() }
                )
            } else if statusViewModel.needsMachineAuth {
                MachineAuthBanner()
            }
            if homePageAvailability == .unavailable {
                GatewayUnreachableBanner(onSettings: onSettings,
                                         onFindGateways: { showingGatewayPicker = true })
            }
            if let text = session.originRefusedText {
                OriginRefusedBanner(text: text)
            }
            // The one picker presentation lives here (F4 §4.7), so Find, Change,
            // the connecting hint's button and the error page's all go through
            // it and two sheets can never overlap (M5 review). The load is
            // stopped first, which moves the page to a failed state with cause
            // `stopped` — so cancelling the picker lands on an error page with
            // Try again, never back on a blank web view.
            BrowserView(model: tab.viewModel,
                        gatewayMissing: homePageAvailability == .unavailable,
                        onChooseGateway: {
                            tab.viewModel.stopForGatewayChange()
                            showingGatewayPicker = true
                        })
                .frame(minHeight: 0, maxHeight: .infinity)
                .layoutPriority(-1)
            // R31, R33: the two clocks that end the app, warned about ahead.
            // At the bottom: the top edge is the app bar's and the node's
            // banners'.
            ForEach(expiryWarnings, id: \.self) { message in
                Label(message, systemImage: "clock.badge.exclamationmark")
