// MARK: - F5 §7: the gateway switcher in Settings

/// Two known gateways, dash (the fake dashboard, current) and gw: Settings
/// names the current one, labels gw from a sweep within R39's first-result
/// budget, and one tap loads it -- proved by gw's own request log. A
/// relaunch keeps the list, now with dash as the other gateway.
func testTheSwitcherListsTheCurrentGatewayAndSwitchesToAnother() async throws {
    try await resetHarness()
    let app = launch(extra: ["-UITestHomePage", "https://dash.tail-scale.ts.net",
                             "-UITestKnownGateways", "https://dash.tail-scale.ts.net,https://\(Self.gatewayHost)"])
    try await waitForDashPage()
    try openSettings(app)
    XCTAssertEqual(element(app, "gateway-current").value as? String, "dash.tail-scale.ts.net",
                   "Settings names the gateway in use")
    let row = element(app, "gateway-switch-\(Self.gatewayHost)")
    XCTAssertTrue(row.appears(within: 5), "the other known gateway has a row")
    let shown = ContinuousClock.now
    XCTAssertTrue(waitForValue(row, "answering", timeout: 15), "gw is labelled answering: \(row.value ?? "nil")")
    XCTAssertLessThanOrEqual(ContinuousClock.now - shown, .seconds(5), "within R39's first-result budget")

    try await resetFakes()
    row.tap()
    XCTAssertTrue(app.navigationBars["Settings"].disappears(within: 10), "a switch closes Settings")
    XCTAssertTrue(element(app, "token-sheet").appears(within: 45), "gw loads and asks for a token")
    let requests = try await gatewayState()["requests"] as? [String] ?? []
    XCTAssertTrue(requests.contains("GET /"), "gw's own log has the page load: \(requests.prefix(6))")
    app.terminate()

    let again = XCUIApplication()
    again.launchArguments = ["-TestControlURL", Self.controlURL]   // the same workspace
    again.launch()
    defer { again.terminate() }
    let sheet = element(again, "token-sheet")
    XCTAssertTrue(sheet.appears(within: 60), "the relaunch opens gw")
    // The sheet is in the tree from the first frame of its slide, when a
    // tap on Close reaches nothing and the sheet stays over the gear.
    element(again, "token-sheet-close").tapWhenSettled(in: again)
    XCTAssertTrue(sheet.disappears(within: 10), "Close closes the token sheet")
    try openSettings(again)
    XCTAssertEqual(element(again, "gateway-current").value as? String, Self.gatewayHost, "gw is current after a relaunch")
    XCTAssertTrue(element(again, "gateway-switch-dash.tail-scale.ts.net").appears(within: 5),
                  "and dash is remembered")
}

/// F1 §4.2: the saved gateway on a port discovery does not probe by
/// default (9443) is probed on it by Settings → Find gateways…, and listed.
func testFindGatewaysProbesTheSavedNonStandardPort() async throws {
    try await resetHarness(gatewayPort: 9443)
    let app = launch(extra: ["-UITestHomePage", "https://\(Self.gatewayHost):9443"])
    defer { app.terminate() }
    var requests: [String] = []
    for _ in 0..<120 where !requests.contains("GET /") {
        try await Task.sleep(for: .milliseconds(500))
        requests = try await gatewayState()["requests"] as? [String] ?? []
    }
    XCTAssertTrue(requests.contains("GET /"), "the saved gateway loads on 9443: \(requests.prefix(6))")
    let sheet = element(app, "token-sheet")
    if sheet.appears(within: 5) {
        element(app, "token-sheet-close").tapWhenSettled(in: app)
        XCTAssertTrue(sheet.disappears(within: 10))
    }
    try await resetFakes()
    try openSettings(app)
    let find = element(app, "settings-find-gateways")
    for _ in 0..<4 where !(find.exists && find.isHittable) { app.swipeUp() }
    find.tap()
    XCTAssertTrue(element(app, "gateway-\(Self.gatewayHost):9443").appears(within: 15),
                  "the saved port was probed and answered as a gateway")
    // gw serves 9443 only, so the row can only have come from a probe
    // there. (The request log cannot show it: the loaded page keeps
    // making its own requests.)
    XCTAssertFalse(element(app, "gateway-\(Self.gatewayHost)").exists, "nothing answered on 443")
}

/// A known gateway that does not answer (plain serves nothing) says so
/// once the sweep ends, and stays tappable: the label is a forecast, and
/// F4 reports the real load, with its way to another gateway.
func testAKnownGatewayThatDoesNotAnswerIsLabelledAndF4ShowsIt() async throws {
    try await resetHarness()
    let app = launch(extra: ["-UITestHomePage", "https://dash.tail-scale.ts.net",
                             "-UITestKnownGateways", "https://dash.tail-scale.ts.net,https://plain.tail-scale.ts.net"])
    defer { app.terminate() }
    try await waitForDashPage()
    try openSettings(app)
    let row = element(app, "gateway-switch-plain.tail-scale.ts.net")
    XCTAssertTrue(row.appears(within: 5))
    XCTAssertTrue(waitForValue(row, "not answering", timeout: 20), "labelled once the sweep ends: \(row.value ?? "nil")")
    XCTAssertTrue(row.isEnabled, "and still tappable")
    row.tap()
    XCTAssertTrue(element(app, "nav-error-overlay").appears(within: 45), "F4: the failed load is shown")
    XCTAssertTrue(element(app, "nav-error-choose-gateway").exists, "with a way to another gateway")
}

/// A known gateway the tailnet does not carry cannot be chosen: it would
/// load direct, off the tailnet, and become the sign-in origin.
func testAKnownGatewayOffTheTailnetCannotBeChosen() async throws {
    try await resetHarness()
    let app = launch(extra: ["-UITestHomePage", "https://dash.tail-scale.ts.net",
                             "-UITestKnownGateways", "https://dash.tail-scale.ts.net,https://gateway.example.com"])
    defer { app.terminate() }
    try await waitForDashPage()
    try openSettings(app)
    let row = element(app, "gateway-switch-gateway.example.com")
    XCTAssertTrue(row.appears(within: 5))
    XCTAssertEqual(row.value as? String, "not on this tailnet")
    XCTAssertFalse(row.isEnabled, "the row is disabled")
    row.tap()
    try await Task.sleep(for: .seconds(2))
    XCTAssertTrue(app.navigationBars["Settings"].exists, "a tap does nothing: Settings stays")
    XCTAssertEqual(element(app, "gateway-current").value as? String, "dash.tail-scale.ts.net", "and dash is still current")
}

// MARK: - F22: the gateway row in the app bar

/// Four remembered gateways, dash in use. The app bar's row has a chip
/// for each, dash first; each other chip's light is a probe of its own
/// gateway -- gw answers (and its log has the probe), plain does not,
/// and a host off the tailnet is grey and cannot be chosen. One tap on
/// gw loads it, proved by gw's own log, and gw is then the chip in use
/// while dash, a web page but not KiroCrew, is lit red.
func testTheAppBarRowLightsEachGatewayAndSwitchesInOneTap() async throws {
    try await resetHarness()
    let app = launch(extra: ["-UITestHomePage", "https://dash.tail-scale.ts.net",
                             "-UITestKnownGateways",
                             "https://dash.tail-scale.ts.net,https://\(Self.gatewayHost),"
                                 + "https://plain.tail-scale.ts.net,https://gateway.example.com"])
    defer { app.terminate() }
    try await waitForDashPage()
    showAppBar(app)
    XCTAssertTrue(element(app, "gateway-row").appears(within: 10), "the app bar carries the gateway row")

    let dash = element(app, "gateway-chip-dash.tail-scale.ts.net")
    let gw = element(app, "gateway-chip-\(Self.gatewayHost)")
    let plain = element(app, "gateway-chip-plain.tail-scale.ts.net")
    let away = element(app, "gateway-chip-gateway.example.com")
    XCTAssertTrue(dash.exists && gw.exists && plain.exists && away.exists, "a chip per gateway")
    XCTAssertEqual(dash.label, "dash.tail-scale.ts.net, in use", "dash is the one in use")
    XCTAssertLessThan(dash.frame.minX, away.frame.minX, "the chips are by name")
    XCTAssertLessThan(away.frame.minX, gw.frame.minX, "not by recency")
    XCTAssertLessThan(gw.frame.minX, plain.frame.minX, "every one of them")
    let frames = { [dash, away, gw, plain].map { $0.frame } }
    let early = frames()

    XCTAssertTrue(waitForValue(gw, "answering", timeout: 15), "gw is lit answering: \(gw.value ?? "nil")")
    let probed = try await gatewayState()["requests"] as? [String] ?? []
    XCTAssertTrue(probed.contains("GET /manifest.json"), "gw's own log has the probe: \(probed.prefix(6))")
    XCTAssertTrue(waitForValue(plain, "not answering", timeout: 20), "plain is lit not answering: \(plain.value ?? "nil")")
    XCTAssertTrue(plain.isEnabled, "a red chip still switches: the light is a forecast")
    XCTAssertEqual(away.value as? String, "not on this tailnet")
    XCTAssertFalse(away.isEnabled, "a host off the tailnet cannot be chosen")
    // Issue #7: a probe's verdict resizes no chip, so none moves.
    let before = frames()
    XCTAssertEqual(before, early, "the verdicts landing moved no chip")

    try await resetFakes()
    gw.tap()
    let sheet = element(app, "token-sheet")
    XCTAssertTrue(sheet.appears(within: 45), "gw loads and asks for a token")
    let requests = try await gatewayState()["requests"] as? [String] ?? []
    XCTAssertTrue(requests.contains("GET /"), "gw's own log has the page load: \(requests.prefix(6))")
    element(app, "token-sheet-close").tapWhenSettled(in: app)
    XCTAssertTrue(sheet.disappears(within: 10), "Close closes the token sheet")
    // Signed out, the sign-in capsule pins the bar, and the row stays
    // beside it: the way back matters most then.
    let gwNow = element(app, "gateway-chip-\(Self.gatewayHost)")
    XCTAssertTrue(gwNow.appears(within: 10), "the row is still in the bar")
    XCTAssertEqual(gwNow.label, "\(Self.gatewayHost), in use", "gw is now the one in use")
    XCTAssertTrue(waitForValue(element(app, "gateway-chip-dash.tail-scale.ts.net"), "not KiroCrew", timeout: 15),
                  "dash answers, but not as KiroCrew")
    // Issue #7: the switch and the sign-out moved no chip. dash was in
    // use and signed in; now gw is, signed out, with the sign-in button
    // up and dash lit red. Every chip is where it was, at its width.
    XCTAssertTrue(element(app, "session-signin-button").exists, "signed out: the sign-in button")
    XCTAssertTrue(app.settles(within: 10), "nothing is sliding")
    XCTAssertEqual(frames(), before, "neither the switch nor the sign-out moved a chip")
    XCTAssertLessThanOrEqual(element(app, "gateway-row").frame.maxX,
                             element(app, "session-signin-button").frame.minX,
                             "sign-in comes after the row, not before it")
}

/// One remembered gateway: nothing to switch to, so no row, and the bar
/// is as F15 left it.
func testTheAppBarRowIsAbsentWithOneGateway() async throws {
    try await resetHarness()
    let app = launch(extra: ["-UITestHomePage", "https://dash.tail-scale.ts.net",
                             "-UITestKnownGateways", "https://dash.tail-scale.ts.net"])
    defer { app.terminate() }
    try await waitForDashPage()
    showAppBar(app)
    XCTAssertTrue(app.buttons["settings-button"].firstMatch.isHittable, "the bar is up")
    XCTAssertFalse(element(app, "gateway-row").exists, "and has no gateway row")
}

/// While the row is up, each other gateway is asked again every
/// `freshFor` (30 s, F22 §4), not every other pass: the pass that finds
/// the last verdict a few milliseconds short of 30 s old must not skip it.
func testTheAppBarRowAsksAgainEveryThirtySeconds() async throws {
    try await resetHarness()
    let app = launch(extra: ["-UITestHomePage", "https://dash.tail-scale.ts.net",
                             "-UITestKnownGateways",
                             "https://dash.tail-scale.ts.net,https://\(Self.gatewayHost)"])
    defer { app.terminate() }
    try await waitForDashPage()
    showAppBar(app)
    let gw = element(app, "gateway-chip-\(Self.gatewayHost)")
    XCTAssertTrue(waitForValue(gw, "answering", timeout: 15), "gw is lit answering: \(gw.value ?? "nil")")
    try await resetFakes()
    let asked = Date()
    var probed = false
    while !probed, Date().timeIntervalSince(asked) < 42 {
        try await Task.sleep(for: .milliseconds(500))
        probed = (try await gatewayState()["requests"] as? [String] ?? []).contains("GET /manifest.json")
    }
    XCTAssertTrue(probed, "gw is asked again within 30 s and a margin")
    XCTAssertTrue(app.buttons["settings-button"].firstMatch.isHittable, "with the bar up all along")
}

/// Signed out at the largest text size, the sign-in capsule shares the
/// bar with the row, and neither pushes the gear off the screen: it is
/// the way to Settings, and F15 §9 makes it always reachable.
func testTheAppBarRowKeepsTheGearOnScreenAtTheLargestText() async throws {
    try await resetHarness()
    let app = launch(extra: ["-UITestHomePage", "https://\(Self.gatewayHost)",
                             "-UITestKnownGateways",
                             "https://\(Self.gatewayHost),https://dash.tail-scale.ts.net",
                             "-UIPreferredContentSizeCategoryName",
                             "UICTContentSizeCategoryAccessibilityXXXL"])
    defer { app.terminate() }
    let sheet = element(app, "token-sheet")
    XCTAssertTrue(sheet.appears(within: 45), "gw loads and asks for a token")
    element(app, "token-sheet-close").tapWhenSettled(in: app)
    XCTAssertTrue(sheet.disappears(within: 10), "Close closes the token sheet")
    XCTAssertTrue(element(app, "session-signin-button").appears(within: 10), "signed out: the capsule")
    XCTAssertTrue(element(app, "gateway-row").exists, "beside the row")
    XCTAssertTrue(app.settles(within: 10), "nothing is sliding")
    let gear = app.buttons["settings-button"].firstMatch
    let screen = app.windows.firstMatch.frame
    XCTAssertTrue(screen.contains(gear.frame), "the gear is on the screen: \(gear.frame) in \(screen)")
    XCTAssertTrue(gear.isHittable, "and can be tapped")
}

/// Brings the app bar in if the page has taken it away (F15): a drag down.
private func showAppBar(_ app: XCUIApplication) {
    let gear = app.buttons["settings-button"].firstMatch
    XCTAssertTrue(gear.appears(within: 10), "the gear exists")
    XCTAssertTrue(app.settles(within: 10), "nothing is sliding")
    if !gear.isHittable {
        let web = app.webViews.firstMatch
        web.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.3))
            .press(forDuration: 0.05, thenDragTo: web.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.7)))

func testFindFromTheUnreachableBannerSwitchesGateway() async throws {
    try await resetHarness()
    let app = XCUIApplication()
    app.launchArguments = ["-UITestResetWorkspaces", "-TestControlURL", Self.controlURL,
                           "-UITestHomePage", "https://gone.tail-scale.ts.net"]
    app.launch()
    defer { app.terminate() }

    let find = element(app, "gateway-unreachable-find-button")
    XCTAssertTrue(find.appears(within: 60), "a gateway not in the tailnet: the banner offers Find")
    find.tapWhenSettled(in: app)
    let gw = element(app, "gateway-\(Self.gatewayHost)")
    XCTAssertTrue(gw.appears(within: 15), "Find sweeps and lists the gateway")
    gw.tapWhenSettled(in: app)
    XCTAssertTrue(element(app, "token-sheet").appears(within: 45),
                  "the new gateway loads, and its token sheet appears after the picker has gone")
    XCTAssertTrue(element(app, "token-sheet-target").label.hasSuffix(Self.gatewayHost))
}

